package me.zenith.skypvp.manager;
import me.zenith.skypvp.ZenithSkyPvP; import org.bukkit.Bukkit; import org.bukkit.ChatColor; import org.bukkit.entity.Player;
public class TabManager {private final ZenithSkyPvP p; public TabManager(ZenithSkyPvP p){this.p=p;} public void updateAll(){if(!p.getConfig().getBoolean("tab.enabled",true))return; for(Player x:Bukkit.getOnlinePlayers()){String h=p.getConfig().getString("tab.header","").replace("%online%",String.valueOf(Bukkit.getOnlinePlayers().size())); String f=p.getConfig().getString("tab.footer","").replace("%online%",String.valueOf(Bukkit.getOnlinePlayers().size())).replace("%max%",String.valueOf(p.getConfig().getInt("max-players",200))).replace("%domain%",p.getConfig().getString("domain")); x.setPlayerListHeaderFooter(color(h),color(f));}} private String color(String s){return ChatColor.translateAlternateColorCodes('&',s);}}
